(() => {
'use strict';
const $ = (s,root=document) => root.querySelector(s);
const $$ = (s,root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name,cls='') => `<svg class="${cls}" aria-hidden="true"><use href="#i-${name}"/></svg>`;
const clone = x => JSON.parse(JSON.stringify(x));
const fmt = n => Number(n).toLocaleString('en-US');
const models=[
 {id:'claude',name:'Claude',letter:'C',color:'#ba866d',role:'策划与架构',desc:'梳理需求、划分模块，让团队从同一个目标出发。'},
 {id:'gpt',name:'GPT',letter:'G',color:'#648f82',role:'开发与整合',desc:'负责实现与内容整合，把各个工作包组合成交付物。'},
 {id:'gemini',name:'Gemini',letter:'✧',color:'#8790bb',role:'设计与表达',desc:'组织信息与视觉结构，为作品建立一致的表达。'},
 {id:'deepseek',name:'DeepSeek',letter:'D',color:'#697cac',role:'检查与测试',desc:'对照需求检查遗漏、识别风险，给出可追踪的意见。'},
 {id:'local',name:'本地模型',letter:'L',color:'#9b8bac',role:'检索与文档',desc:'使用本地模型处理资料、维护文档，也可承担自定义角色。'}
];
const presets=[
 {id:'project',name:'把项目，向前推进',title:'一起做成\n一件事',en:'项目计划',tag:'FROM IDEA TO DONE',desc:'需求拆解 · 协作分工 · 验收',icon:'branch',brief:'新产品从想法到发布\n整理目标与范围，拆分任务、明确交付物，并建立逐项验收清单。'},
 {id:'ppt',name:'一份出彩的演示',title:'让想法\n登场',en:'演示文稿',tag:'MAKE YOUR POINT',desc:'内容策划 · 视觉设计 · 审阅',icon:'slides',brief:'新产品发布提案\n面向团队介绍产品目标、协作策略与阶段计划，用简洁的视觉讲清楚想法。'},
 {id:'website',name:'把灵感变成网站',title:'从 0 到 1\n即刻上线',en:'网站页面',tag:'BUILD SOMETHING NEW',desc:'页面策划 · 开发实现 · 检查',icon:'globe',brief:'独立创作者的个人主页\n用温暖、简洁的风格展示个人介绍、服务特色与联系方式。'},
 {id:'code',name:'代码，有人一起想',title:'好代码\n一起写',en:'代码开发',tag:'BETTER CODE TOGETHER',desc:'架构设计 · 编写代码 · 测试',icon:'code',brief:'轻量待办事项应用\n支持添加任务、完成状态切换与删除，用单页 HTML 实现一个可继续开发的原型。'},
 {id:'document',name:'把日常工作理清',title:'日常琐事\n有条不紊',en:'日常文档',tag:'LESS FRICTION, MORE FLOW',desc:'资料整理 · 方案写作 · 校对',icon:'doc',brief:'本周工作总结与下周计划\n整理已完成事项、正在推进的任务、需要协调的问题和下周优先级。未提供的事实留待补充。'}
];
let saved={};try{saved=JSON.parse(localStorage.getItem('gongming-v1')||'{}');}catch{}
let state={view:'discover',budget:Number(saved.budget)||12000,crew:Array.isArray(saved.crew)&&saved.crew.length?saved.crew.filter(id=>models.some(m=>m.id===id)):['claude','gemini','deepseek'],favorites:Array.isArray(saved.favorites)?saved.favorites:[],tasks:Array.isArray(saved.tasks)?saved.tasks.filter(t=>t&&presets.some(p=>p.id===t.kind)&&Array.isArray(t.versions)&&Array.isArray(t.comments)):[],current:null,tab:'preview',slide:0,version:0,search:'',running:null,paused:false,step:0};
if(!state.crew.length)state.crew=['claude','gemini','deepseek'];
let toastTimer,runTimer;
const seeds=[{id:'sample-ppt',kind:'ppt',title:'新产品发布提案',brief:presets[1].brief},{id:'sample-website',kind:'website',title:'独立创作者的个人主页',brief:presets[2].brief},{id:'sample-project',kind:'project',title:'新产品从想法到发布',brief:presets[0].brief}];
function persist(){try{localStorage.setItem('gongming-v1',JSON.stringify({budget:state.budget,crew:state.crew,favorites:state.favorites,tasks:state.tasks.slice(0,30)}));}catch{toast('浏览器存储已满；本次修改仍在内存中，请导出作品。');}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function current(){return state.tasks.find(t=>t.id===state.current);}
function artOf(task=current()){return task?.versions?.[Math.min(state.version,task.versions.length-1)]?.artifact;}
function estimate(task){const brief=task?.brief||'';let ascii=0,other=0;for(const c of brief){if(c.codePointAt(0)<128)ascii++;else other++;}const input=Math.ceil(ascii/3+other)+550;const n=(task?.crew||state.crew).length;return{input:input*n,output:1200*n,total:(input+1200)*n};}
function avatar(id){const m=models.find(m=>m.id===id);return m?`<span style="background:${m.color}" title="${m.name}">${m.letter}</span>`:'';}
function presetCard(p){const loved=state.favorites.includes(p.id);return `<article class="preset"><button class="preset-cover cover-${p.id}" data-preset="${p.id}" aria-label="使用${p.name}方案"><span class="cover-meta">${p.en}</span><span class="cover-title">${p.title.replace('\n','<br>')}</span><span class="cover-art"></span><span class="cover-tag">${p.tag}</span><span class="cover-play">${icon('play')}</span></button><div class="preset-info"><button data-preset="${p.id}">${p.name}</button><button class="icon-btn ${loved?'is-favorite':''}" data-favorite="${p.id}" aria-label="${loved?'取消收藏':'收藏'}${p.name}" aria-pressed="${loved}">${icon('heart')}</button></div><p>${p.desc}</p></article>`;}
function rows(tasks){return `<div class="table-head"><span>#</span><span>任务名称</span><span>协作团队</span><span>状态</span><span>类型</span><span></span></div>${tasks.map((t,i)=>{const p=presets.find(p=>p.id===t.kind);const ready=t.versions?.length;return `<button class="task-row" data-task="${esc(t.id)}"><span class="row-index">${String(i+1).padStart(2,'0')}</span><span class="task-name"><span class="file-icon ${t.kind}">${icon(p.icon)}</span><span><b>${esc(t.title)}</b><small>${t.sample||t.id.startsWith('sample-')?'示例项目 · 本地模板演示':`我的项目 · ${esc(t.created||'刚刚')}`}</small></span></span><span class="row-team">${(t.crew||state.crew).slice(0,3).map(avatar).join('')}<small>${(t.crew||state.crew).length} 位成员</small></span><span class="status-badge ${ready?'ready':''}">${t.approved?'已定稿':t.id===state.running?'演示进行中':ready?'待审阅':'待开始'}</span><span class="row-time">${{ppt:'演示文稿',website:'网站',code:'开发',project:'项目计划',document:'工作文档'}[t.kind]}</span>${icon('chevron','row-open')}</button>`;}).join('')}`;}
function getAllTasks(){return [...state.tasks,...seeds.filter(s=>!state.tasks.some(t=>t.id===s.id))];}
function renderHome(){const q=state.search.toLowerCase();const ps=presets.filter(p=>(p.name+p.desc+p.brief).toLowerCase().includes(q));$('#presetGrid').innerHTML=ps.length?ps.map(presetCard).join(''):'<p class="no-search">没有匹配的方案</p>';const tasks=getAllTasks().filter(t=>(t.title+t.brief).toLowerCase().includes(q));$('#recentTasks').innerHTML=tasks.length?rows(tasks.slice(0,q?20:3)):'<p class="no-search">没有匹配的任务，试试其他关键词。</p>';$('#taskSubtitle').textContent=q?`搜索结果 · ${tasks.length} 个任务`:'本地体验记录 · 不调用模型';}
function refreshChrome(){const t=current();$('#headerBudget').textContent=fmt(state.budget);$('#ringBudget').textContent=(state.budget/1000).toLocaleString('en-US',{maximumFractionDigits:1})+'k';$('#playerTitle').textContent=t?t.title:'选择一个任务';$('#playerDescription').textContent=t?`${presets.find(p=>p.id===t.kind).name} · ${t.versions.length?'作品已就绪，点击查看':'本地协作流程演示'}`:'打开模板，体验协作与审阅';$('#playerArt').innerHTML=icon(t?presets.find(p=>p.id===t.kind).icon:'branch');const crew=t?.crew||state.crew;$('#playerAvatars').innerHTML=crew.map(avatar).join('');$('#playerTeamCount').textContent=`${crew.length} 位协作成员`;const active=Boolean(state.running);$('#playerStart').innerHTML=active&&!state.paused?'<span style="font-size:13px;font-weight:600">Ⅱ</span>':icon(t?.versions.length&&!active?'grid':'play');$('#playerStart').setAttribute('aria-label',active?(state.paused?'继续演示':'暂停演示'):t?.versions.length?'查看作品':'开始协作');$('#playerStatus').textContent=active?(state.paused?'已暂停':'协作演示中'):t?.versions.length?'查看作品':'开始协作';const progress=active?Math.min(95,Math.round(state.step/5*100)):t?.versions.length?100:0;$('#progressFill').style.width=progress+'%';$('#progressPercent').textContent=progress+'%';$('#progressLabel').textContent=active?(state.paused?'已暂停':'演示中'):t?.versions.length?'已就绪':'待开始';$('#favoriteCurrent').classList.toggle('is-favorite',Boolean(t&&state.favorites.includes(t.kind)));if(state.view==='runtime'){$('#playerTitle').textContent='本地项目协作';$('#playerDescription').textContent='任务进度、审批和结果，集中在项目看板';$('#playerArt').innerHTML=icon('branch');$('#playerStart').innerHTML=icon('settings');$('#playerStart').setAttribute('aria-label','连接模型');$('#playerStatus').textContent='连接模型';$('#progressLabel').textContent='本机';$('#progressFill').style.width='0%';$('#progressPercent').textContent='';$('#playerTeamCount').textContent='按角色分配模型';$('#playerAvatars').innerHTML='';}}
function openView(view){if(!['discover','workspace','team','history','favorites','library','runtime','chat','results','extensions','projects','workflows','artifacts','automation','settings'].includes(view))return;state.view=view;document.body.dataset.view=view;document.dispatchEvent(new Event('gongming:view-changed'));document.body.classList.remove('chat-sidebar-open');try{localStorage.setItem('gongming.last-view',view);}catch{}$$('.view').forEach(v=>v.classList.remove('active'));if(view==='chat'&&!$('#chatView')){const el=document.createElement('section');el.id='chatView';el.className='view';$('#mainContent').append(el);}if(view==='runtime'&&!$('#runtimeView')){const el=document.createElement('section');el.id='runtimeView';el.className='view';$('#mainContent').append(el);}if(!$('#'+view+'View')){const section=document.createElement('section');section.id=view+'View';section.className='view';$('#mainContent').append(section);}$('#'+view+'View').classList.add('active');$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').textContent={discover:'工作台',workspace:'作品审阅',team:'模型与成员',history:'最近任务',favorites:'收藏方案',library:'作品库',runtime:'高级工作台',chat:'对话',results:'作品与任务',extensions:'技能与 MCP',projects:'项目',workflows:'工作流',artifacts:'产物',automation:'自动化',settings:'设置'}[view];if(view==='chat')window.ChatUI?.render();if(view==='discover'){renderHome();window.WorkHub?.render();}if(view==='results')window.WorkHub?.results();if(view==='extensions')window.ExtensionsUI?.render();if(view==='workspace')renderWorkspace();if(view==='team')renderTeam();if(view==='history')renderHistory();if(view==='favorites')renderFavorites();if(view==='library')renderLibrary();if(view==='runtime'){if(window.RuntimeUI)window.RuntimeUI.render();else $('#runtimeView').innerHTML='<div class="empty-state"><h3>本地服务面板加载中</h3><p>请稍后刷新页面。</p></div>';}window.NavigationUI?.render(view);refreshChrome();window.scrollTo({top:0,behavior:'instant'});}
function createTask(kind,brief,crew=state.crew){const task={id:'task-'+Date.now().toString(36),kind,title:brief.split('\n').find(l=>l.trim())?.slice(0,36)||'新的示例任务',brief,crew:[...crew],versions:[],comments:[],created:new Date().toLocaleDateString('zh-CN'),approved:false};state.tasks.unshift(task);state.current=task.id;state.version=0;state.slide=0;state.tab='preview';persist();openView('workspace');return task;}
function openTask(id){let t=state.tasks.find(t=>t.id===id);if(!t){const s=seeds.find(s=>s.id===id);if(!s)return;t={...s,sample:true,crew:[...state.crew],versions:[{artifact:ArtifactEngine.create(s.kind,s.brief),note:'示例初稿',time:Date.now()}],comments:[],created:'示例',approved:false};state.tasks.unshift(t);persist();}state.current=id;state.version=Math.max(0,t.versions.length-1);state.slide=0;state.tab='preview';openView('workspace');}
function showDialog(html){$('#dialogContent').innerHTML=`<div class="dialog-inner">${html}</div>`;if(!$('#mainDialog').open)$('#mainDialog').showModal();}
function closeDialog(){$('#mainDialog').close();}
function dialogHeading(title,subtitle){return `<div class="dialog-header"><div><h2>${title}</h2><p>${subtitle}</p></div><button data-action="close" class="icon-btn" aria-label="关闭">${icon('close')}</button></div>`;}
async function newDialog(kind='project') {
 let chosen=presets.some(p=>p.id===kind)?kind:'project';
 showDialog(dialogHeading('开始一个协作任务','说清目标，总控会按团队分工安排模型，完成后在对话里审阅。')+ `<label class="field-label">想要完成什么</label><div class="type-options">${presets.map(p=>`<button type="button" class="type-option ${p.id===chosen?'selected':''}" data-kind="${p.id}">${icon(p.icon)}${{project:'通用项目',ppt:'演示文稿',website:'网站',code:'代码',document:'日常工作'}[p.id]}</button>`).join('')}</div><label class="field-label" for="taskBrief">描述需求与交付标准</label><textarea class="form-textarea" id="taskBrief" maxlength="12000">${esc(presets.find(p=>p.id===chosen).brief)}</textarea><div class="task-team-heading"><label class="field-label">协作模型与分工</label><div class="button-row"><button type="button" class="outline-button" id="taskAddModel">＋ 添加模型</button><button type="button" class="text-link" id="taskAssignModels">调整分工</button></div></div><div id="taskConnectedModels" class="task-connected-models" role="status">正在读取已连接模型…</div><p id="taskCreateError" role="alert"></p><div class="dialog-footer"><button type="button" class="text-link" id="taskLocalExample">仅体验本地示例</button><button type="button" class="primary-button" id="createRealTask" disabled>开始协作 ${icon('arrow')}</button></div>`);
 const panel=$('#mainDialog'),target=$('#taskConnectedModels'),create=$('#createRealTask');
 async function refreshTeam(){
  if(!panel.open||!target.isConnected)return;
  try{const response=await fetch('/api/status',{cache:'no-store',signal:AbortSignal.timeout(15000)}),data=await response.json();if(!response.ok||data.mode!=='local')throw Error('本地服务未连接');if(!target.isConnected)return;target.innerHTML=window.TeamUI.roster(data.config);target.querySelector('[data-action=connect]')?.addEventListener('click',event=>{event.stopPropagation();window.RuntimeUI?.openSettings();});create.disabled=!data.capabilities?.model;if(create.disabled)target.insertAdjacentHTML('beforeend','<p class="rt-hint">先添加可用模型；需求会保留在此窗口。</p>');}
  catch(e){if(target.isConnected){target.textContent='无法读取本机模型，请检查本地服务后重试。';create.disabled=true;}}
 }
 const onClose=event=>{if(event.target===panel){document.removeEventListener('close',onClose,true);}else if(target.isConnected)refreshTeam();};document.addEventListener('close',onClose,true);
 panel.querySelectorAll('[data-kind]').forEach(button=>button.onclick=()=>{const field=$('#taskBrief'),unchanged=field.value===presets.find(p=>p.id===chosen).brief;chosen=button.dataset.kind;if(unchanged)field.value=presets.find(p=>p.id===chosen).brief;panel.querySelectorAll('[data-kind]').forEach(node=>node.classList.toggle('selected',node===button));});
 $('#taskAddModel').onclick=()=>window.RuntimeUI?.openSettings();$('#taskAssignModels').onclick=()=>window.ConnectionsUI?.team();
 $('#taskLocalExample').onclick=()=>{const brief=$('#taskBrief').value.trim();if(!brief){$('#taskBrief').focus();return;}closeDialog();createTask(chosen,brief);};
 create.onclick=async()=>{const brief=$('#taskBrief').value.trim();if(brief.length<3){$('#taskCreateError').textContent='请填写至少 3 个字符的任务目标。';$('#taskBrief').focus();return;}closeDialog();await window.RuntimeUI?.startTask({brief,kind:chosen});};
 await refreshTeam();
}
function budgetDialog(){showDialog(dialogHeading('少一点消耗，多一点成果','设置单任务预算，超出估算时先停下来确认。')+`<div class="budget-value"><b id="budgetNumber">${fmt(state.budget)}</b><span>tokens / 任务</span></div><input type="range" min="1000" max="64000" step="1000" value="${state.budget}" id="budgetRange" aria-label="单任务 Token 预算"><div class="range-labels"><span>1,000</span><span>32,000</span><span>64,000</span></div><div class="settings-note"><b>按角色选择上下文，按需安排成员。</b><br>这里的 Token 数是字符估算，包含每位成员的输入与输出预留，并非模型实际账单。多家模型不会因为使用同一提示词而共享计费缓存。<br><br>本地模板模式不调用 API，实际消耗为 0。真实任务以服务端返回的 usage 为准。</div><div class="dialog-footer"><button class="text-link" data-action="connect">配置本地模型 / API ${icon('chevron')}</button><button class="primary-button" id="saveBudget">保存预算</button></div>`);$('#budgetRange').oninput=e=>$('#budgetNumber').textContent=fmt(e.target.value);$('#saveBudget').onclick=()=>{state.budget=Number($('#budgetRange').value);persist();refreshChrome();if(state.view==='workspace')renderWorkspace();closeDialog();toast('单任务预算已更新');};}
function runTask(){const t=current();if(!t){newDialog();return;}if(t.versions.length){openView('workspace');return;}if(state.running){if(state.running===t.id){state.paused=!state.paused;refreshChrome();if(state.view==='workspace')renderWorkspace();return;}toast('一个演示任务正在进行，请等待它完成');return;}const est=estimate(t);if(est.total>state.budget){toast(`预计需 ${fmt(est.total)} tokens，超过当前预算。请减少成员或调整预算。`);budgetDialog();return;}state.running=t.id;state.paused=false;state.step=0;state.tab='activity';openView('workspace');clearInterval(runTimer);runTimer=setInterval(()=>{if(state.paused)return;state.step++;if(state.step>=5){clearInterval(runTimer);const task=state.tasks.find(task=>task.id===state.running);if(task){task.versions.push({artifact:ArtifactEngine.create(task.kind,task.brief),note:'本地模板初稿',time:Date.now()});task.sample=false;persist();}state.running=null;state.step=0;if(state.current===task?.id){state.tab='preview';state.version=task.versions.length-1;}toast('本地初稿已就绪，可以开始审阅。未调用真实模型。');}if(state.view==='workspace')renderWorkspace();refreshChrome();},650);}
function renderWorkspace(){const t=current();const el=$('#workspaceView');if(!t){el.innerHTML=`<div class="page-heading"><div><h1>让工作，有个好搭档。</h1><p>把目标交给团队，把决定留给自己。</p></div><button class="outline-button" data-view="runtime">真实项目协作 ${icon('arrow')}</button></div><div class="empty-state">${icon('branch')}<h3>从一个需求，开始协作</h3><p>日常工作、项目开发、PPT、网站……<br>为每个任务组建团队，在同一个空间完成审阅。</p><button class="primary-button" data-action="new">${icon('plus')} 新建协作任务</button></div><div class="section-heading"><h2>或者，从熟悉的场景开始</h2></div><div class="preset-grid">${presets.map(presetCard).join('')}</div>`;return;}
const art=artOf(t), est=estimate(t), active=state.running===t.id, pending=t.comments.filter(c=>!c.resolved).length;el.innerHTML=`<div class="page-heading"><div><h1>${esc(t.title)}</h1><p>${art?'在同一处预览、批注、修改，直到每一个细节都准备好。':'先确认需求与分工，再开始这次协作。'}</p></div><div class="button-row">${art?`<button class="outline-button" data-action="edit">${icon('edit')} 编辑作品</button><button class="outline-button" data-action="export">${icon('download')} 导出</button><button class="primary-button" data-action="approve" ${t.approved?'disabled':''}>${icon('check')} ${t.approved?'已定稿':'确认定稿'}</button>`:`<button class="outline-button" data-action="new">${icon('plus')} 新任务</button><button class="primary-button" data-action="run">${icon('play')} ${active?(state.paused?'继续演示':'暂停演示'):'开始本地演示'}</button>`}</div></div><div class="notice">本地模板演示：成员分工与进度用于体验协作流程，尚未调用模型。需要真实项目执行？<button class="text-link" style="color:#b37d55;margin-left:8px" data-view="runtime">打开 项目协作 ${icon('arrow')}</button></div><div class="workspace-layout"><aside class="task-details"><p class="section-caption">THE BRIEF / 任务需求</p><h3>${presets.find(p=>p.id===t.kind).name}</h3><div class="brief-text">${esc(t.brief)}</div><div class="divider-line"></div><p class="section-caption">YOUR TEAM / 协作分工</p>${t.crew.map((id,i)=>{const m=models.find(m=>m.id===id);return `<div class="member"><span class="model-avatar" style="background:${m.color}">${m.letter}</span><div><strong>${m.name}</strong><small>${m.role}</small></div><span class="member-status ${art?'complete':''}">${art?'示例':active?'演示':'待命'}</span></div>`;}).join('')}<div class="divider-line"></div><div class="task-estimate"><span>全团队预估上限</span><b>${fmt(est.total)}</b></div><p style="font-size:8px;color:#b4b2be;line-height:1.8">输入约 ${fmt(est.input)} + 输出预留 ${fmt(est.output)}<br>模型计费以实际 usage 为准，当前消耗 0</p><button class="text-link" data-action="settings">预算 ${fmt(state.budget)} · 调整 ${icon('chevron')}</button></aside><div class="work-panel"><div class="work-toolbar"><div class="tab-buttons"><button data-tab="preview" class="${state.tab==='preview'?'active':''}">成果预览</button><button data-tab="activity" class="${state.tab==='activity'?'active':''}">协作过程</button><button data-tab="compare" class="${state.tab==='compare'?'active':''}">版本对比</button></div>${art?`<select class="version-select" id="versionSelect" aria-label="选择作品版本">${t.versions.map((v,i)=>`<option value="${i}" ${i===state.version?'selected':''}>V${i+1} · ${esc(v.note)}</option>`).join('')}</select>`:'<span class="demo-pill">DEMO</span>'}</div><div id="workBody"></div>${art?`<section class="review-panel"><div class="review-heading"><h3>一起审阅 <span>${pending} 条待处理</span></h3><span class="text-link">意见与版本保存在当前浏览器</span></div><form id="reviewForm" class="review-form"><select id="reviewAnchor" aria-label="审阅位置">${anchors(art).map((a,i)=>`<option value="${i}" ${i===state.slide?'selected':''}>${esc(a)}</option>`).join('')}</select><input id="reviewText" placeholder="这里可以再优化一下……" aria-label="审阅意见" maxlength="2000" required><button class="primary-button" type="submit">${icon('plus')} 添加意见</button></form><div class="comments">${t.comments.length?t.comments.map(commentHtml).join(''):'<p class="review-empty">点击添加第一条意见。好的作品，从交流开始。</p>'}</div></section>`:''}</div></div>`;renderWorkBody(t,art);if($('#versionSelect'))$('#versionSelect').onchange=e=>{state.version=Number(e.target.value);state.slide=0;renderWorkspace();};if($('#reviewForm'))$('#reviewForm').onsubmit=e=>{e.preventDefault();const text=$('#reviewText').value.trim();if(!text)return;t.comments.push({id:'c'+Date.now(),text,anchor:Number($('#reviewAnchor').value),label:anchors(art)[Number($('#reviewAnchor').value)],version:state.version+1,resolved:false});t.approved=false;persist();renderWorkspace();};}
function anchors(art){if(art.kind==='ppt')return art.slides.map((s,i)=>`第 ${i+1} 页`);if(art.kind==='website')return['整个页面','首屏 / 关于','特色区块','联系区块'];if(art.kind==='code')return['整体实现','输入与状态','异常与边界','可维护性'];return['全文','目标与范围','主要内容','验收标准'];}
function commentHtml(c){return `<div class="comment ${c.resolved?'resolved':''}"><span class="avatar">K</span><div class="comment-content"><div class="comment-top"><strong>我</strong><button data-comment-anchor="${c.anchor}">${esc(c.label)}</button><span>V${c.version}</span></div><p>${esc(c.text)}</p></div><button class="resolve-button" data-resolve="${c.id}">${c.resolved?'✓ 已解决':'标为已解决'}</button></div>`;}
function frameDocument(html){const security='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; script-src \'unsafe-inline\'; style-src \'unsafe-inline\'; img-src data: blob:; font-src data:; connect-src \'none\'; form-action \'none\';">';return html.replace(/<head>/i,'<head>'+security);}
function renderWorkBody(t,art){const body=$('#workBody');if(state.tab==='activity'){const steps=[['需求与上下文','明确目标、范围和交付标准，建立共享任务说明。'],['架构与规划','按角色拆解工作包，确认前置依赖与检查点。'],['多角色创作','成员按分工产出内容、页面或代码，保留交接信息。'],['联合检查','对照验收标准，汇总需要补充与修改的内容。'],['交付与审阅','将成果集中呈现，由你批注、修改、定稿。']];body.innerHTML=`<div class="activity-list">${steps.map((s,i)=>`<div class="activity-step ${art?'done':state.running===t.id?(i<state.step?'done':i===state.step?'current':''):''}"><h4>${s[0]} ${state.running===t.id&&state.paused&&i===state.step?'· 已暂停':''}</h4><p>${s[1]}</p><small>${art?'本地演示步骤已结束':state.running===t.id?(i<state.step?'演示结束':i===state.step?'演示进行中':'等待前置步骤'):'尚未开始'}</small></div>`).join('')}<div class="settings-note">这是可交互的流程演示。真实 Agent 调度、依赖等待、测试、Git、审批与审计，请进入 <button class="text-link" data-view="runtime">项目协作 →</button></div></div>`;return;}
if(state.tab==='compare'){if(t.versions.length<2){body.innerHTML=`<div class="stage-empty">${icon('branch')}<h3>每一次打磨，都留下版本</h3><p>点击「编辑作品」并保存后，在这里对照前后变化。旧版本始终保留，可以重新查看与导出。</p>${art?'<button class="outline-button" data-action="edit">开始第一次修改</button>':''}</div>`;return;}const right=Math.max(1,state.version);body.innerHTML=`<div class="comparison"><div><h4>V${right} · 修改前</h4><pre>${esc(artifactText(t.versions[right-1].artifact))}</pre></div><div><h4>V${right+1} · 修改后</h4><pre>${esc(artifactText(t.versions[right].artifact))}</pre></div></div>`;return;}
if(!art){body.innerHTML=`<div class="stage-empty">${icon('branch')}<h3>一份需求，多种可能</h3><p>先体验本地协作流程。完成后，作品会出现在这里，支持批注、版本记录与导出。</p><button class="primary-button" data-action="run">${icon('play')} ${state.running===t.id?'查看协作进度':'开始本地演示'}</button></div>`;return;}
body.innerHTML=`<div class="artifact-stage"><div class="stage-label"><span>${esc(art.notice)} · V${state.version+1}</span><span>${t.approved?'✓ 已确认定稿':'等待你的审阅'}</span></div><div id="artifactDisplay"></div>${art.kind==='ppt'?`<div class="stage-controls"><button class="icon-btn" data-slide="-1" aria-label="上一页" ${state.slide===0?'disabled':''}>${icon('chevron','flip')}</button><span>${state.slide+1} / ${art.slides.length}</span><button class="icon-btn" data-slide="1" aria-label="下一页" ${state.slide===art.slides.length-1?'disabled':''}>${icon('chevron')}</button></div>`:''}</div>`;const display=$('#artifactDisplay');if(art.kind==='ppt'||art.kind==='website'){const f=document.createElement('iframe');f.setAttribute('sandbox','allow-scripts');f.title=art.kind==='ppt'?`第 ${state.slide+1} 页幻灯片预览`:'网站作品预览';if(art.kind==='ppt')f.className='slide-frame';display.append(f);window.ApiSession.preview(f,frameDocument(art.kind==='ppt'?ArtifactEngine.slideHtml(art.slides[state.slide],state.slide,art.slides.length):art.html),art.kind==='website');}else{const pre=document.createElement('pre');pre.className=art.kind==='code'?'code-preview':'markdown-preview';pre.textContent=art.code||art.markdown;display.append(pre);}}
function artifactText(art){if(art.kind==='ppt')return art.slides.map((s,i)=>`第 ${i+1} 页 / ${s.title}\n${s.subtitle}\n${s.items.map(it=>it.title+'：'+it.body).join('\n')}`).join('\n\n');if(art.kind==='website')return new DOMParser().parseFromString(art.html,'text/html').body.textContent.trim();return art.code||art.markdown;}
function editArtifact(){const t=current(),art=artOf(t);if(!art)return;if(t.versions.length>=12){toast('此演示最多保留 12 个版本，请导出后新建任务');return;}const slide=art.kind==='ppt'?art.slides[state.slide]:null;showDialog(dialogHeading(slide?`打磨第 ${state.slide+1} 页`:'编辑作品，保存一个新版本','旧版本保持完整；已有审阅意见继续保留。')+(slide?`<label class="field-label" for="editTitle">页面标题</label><input id="editTitle" class="form-input" value="${esc(slide.title)}" maxlength="60"><label class="field-label" for="editContent">副标题</label><textarea id="editContent" class="form-textarea" maxlength="260">${esc(slide.subtitle)}</textarea>${slide.items.length?'<label class="field-label" for="editItems">页面要点（JSON，可直接修改文字）</label><textarea class="form-textarea" id="editItems">'+esc(JSON.stringify(slide.items,null,2))+'</textarea>':''}`:art.kind==='website'?`<label class="field-label" for="editTitle">网站标题</label><input class="form-input" id="editTitle" value="${esc(art.title)}" maxlength="60"><label class="field-label" for="editContent">首屏介绍文案</label><textarea id="editContent" class="form-textarea" maxlength="1500">${esc(new DOMParser().parseFromString(art.html,'text/html').querySelector('.hero p')?.textContent||art.brief)}</textarea>`:`<label class="field-label" for="editContent">${art.kind==='code'?'源代码':'文档内容（Markdown）'}</label><textarea id="editContent" class="form-textarea large" maxlength="100000">${esc(art.code||art.markdown)}</textarea>`)+`<div class="dialog-footer"><small>当前 V${state.version+1} → 新版本 V${t.versions.length+1}<br>手动编辑，不产生模型费用。</small><button class="primary-button" id="saveEdit">${icon('check')} 保存新版本</button></div>`);$('#saveEdit').onclick=()=>{const updated=clone(art);const content=$('#editContent').value;if(slide){const title=$('#editTitle').value.trim();if(!title){toast('请填写页面标题');return;}updated.slides[state.slide].title=title;updated.slides[state.slide].subtitle=content;if($('#editItems')){try{const items=JSON.parse($('#editItems').value);if(!Array.isArray(items)||items.length>4||items.some(i=>typeof i.title!=='string'||typeof i.body!=='string'))throw Error();updated.slides[state.slide].items=items;}catch{toast('要点格式需为包含 title 和 body 的 JSON 数组，最多 4 项');return;}}if(state.slide===0)updated.title=title;}else if(art.kind==='website'){const title=$('#editTitle').value.trim();if(!title){toast('请填写网站标题');return;}const doc=new DOMParser().parseFromString(updated.html,'text/html');doc.querySelector('title').textContent=title;doc.querySelector('.hero h1').textContent=title;doc.querySelector('.hero p').textContent=content;const brand=doc.querySelector('.brand');if(brand){const mark=brand.querySelector('.mark');brand.textContent='';if(mark)brand.append(mark);brand.append(document.createTextNode(title));}updated.title=title;updated.html='<!doctype html>\n'+doc.documentElement.outerHTML;}else if(art.kind==='code')updated.code=content;else updated.markdown=content;t.versions.push({artifact:updated,note:'手动修订',time:Date.now()});state.version=t.versions.length-1;t.approved=false;persist();closeDialog();renderWorkspace();toast(`已保存 V${state.version+1}，可以对照变化并处理审阅意见。`);};}
async function exportArtifact(){const a=artOf();if(!a){toast('先生成一份作品');return;}try{await ArtifactEngine.download(a);toast('已开始导出当前版本');}catch(e){toast('导出失败：'+e.message);}}
function approve(){const t=current();if(!t)return;if(t.comments.some(c=>!c.resolved)){toast('还有待处理的审阅意见。完成修改后，请逐条标为已解决。');return;}if(state.version!==t.versions.length-1){toast('请先切换到最新版本再确认定稿');return;}t.approved=true;persist();renderWorkspace();refreshChrome();toast('已确认定稿，作品已保存在作品库');}
async function renderTeam(){const target=$('#teamView');target.innerHTML='<div class="page-heading"><div><h1>你的协作团队</h1><p>总控安排工作，各角色可以选择不同公司的模型和版本。</p></div><div class="button-row"><button type="button" class="outline-button" data-team-settings>调整分工</button><button type="button" class="primary-button" data-action="connect">＋ 添加模型</button></div></div><div id="teamPageModels" class="task-connected-models" role="status">正在读取模型…</div>';const list=target.querySelector('#teamPageModels');const refresh=async()=>{try{const response=await fetch('/api/status',{signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error();const data=await response.json();if(list.isConnected)list.innerHTML=window.TeamUI.roster(data.config);}catch{if(list.isConnected)list.innerHTML='<p>无法读取模型，请检查本地服务。</p><button type="button" class="outline-button" data-action="connect">连接模型</button>';}};await refresh();const onClose=()=>{if(list.isConnected)refresh();else document.removeEventListener('close',onClose,true);};document.addEventListener('close',onClose,true);}
function renderHistory(){const tasks=getAllTasks().filter(t=>(t.title+t.brief).toLowerCase().includes(state.search.toLowerCase()));$('#historyView').innerHTML=`<div class="page-heading"><div><h1>本地示例记录</h1><p>这里保留模板体验记录；真实任务请在「作品与任务」查看。</p></div><button class="primary-button" data-action="new">${icon('plus')} 新建任务</button></div><div class="task-table">${tasks.length?rows(tasks):'<div class="empty-state">没有匹配的任务</div>'}</div>`;}
function renderFavorites(){const list=presets.filter(p=>state.favorites.includes(p.id));$('#favoritesView').innerHTML=`<div class="page-heading"><div><h1>喜欢的方案，随时重用。</h1><p>把顺手的协作方式收藏起来，下次从容开工。</p></div></div>${list.length?`<div class="preset-grid">${list.map(presetCard).join('')}</div>`:`<div class="empty-state">${icon('heart')}<h3>收藏你的第一个协作方案</h3><p>在方案卡片旁点击爱心，常用方案就会出现在这里。</p><button class="outline-button" data-view="discover">去发现好方案</button></div>`}`;}
function renderLibrary(){const tasks=state.tasks.filter(t=>t.versions.length&&(t.title+t.brief).toLowerCase().includes(state.search.toLowerCase()));$('#libraryView').innerHTML=`<div class="page-heading"><div><h1>灵感的落点，都在这里。</h1><p>所有本地作品与修订版本。真实项目交付物请到 Agent 平台查看。</p></div><button class="outline-button" data-view="runtime">查看真实交付 ${icon('arrow')}</button></div>${tasks.length?`<div class="library-grid">${tasks.map(t=>{const p=presets.find(p=>p.id===t.kind);return `<article class="library-card"><span class="model-avatar">${icon(p.icon)}</span><h3>${esc(t.title)}</h3><p>${t.versions.length} 个版本 · ${t.comments.filter(c=>!c.resolved).length} 条待处理意见<br>${t.approved?'已确认定稿':'本地模板 · 等待审阅'}</p><div class="button-row"><button class="outline-button" data-task="${t.id}">${icon('chat')} 打开审阅</button><button class="text-link" data-export-task="${t.id}">导出最新版本 ${icon('download')}</button></div></article>`;}).join('')}</div>`:`<div class="empty-state">${icon('folder')}<h3>好作品，值得被留下</h3><p>完成一个任务后，作品会自动保存到这里。<br>支持 PPTX、HTML、Markdown 与代码文件导出。</p><button class="primary-button" data-action="new">开始第一个任务</button></div>`}`;}
function favorite(id){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();if(state.view==='discover')renderHome();if(state.view==='favorites')renderFavorites();if(state.view==='workspace'&&!current())renderWorkspace();refreshChrome();}
function connect(){closeDialog();if(window.RuntimeUI)window.RuntimeUI.openSettings();}
document.addEventListener('click',e=>{const btn=e.target.closest('button');if(!btn)return;if(btn.dataset.view){openView(btn.dataset.view);return;}if(btn.dataset.preset){newDialog(btn.dataset.preset);return;}if(btn.dataset.favorite){favorite(btn.dataset.favorite);return;}if(btn.dataset.task){openTask(btn.dataset.task);return;}if(btn.dataset.tab){state.tab=btn.dataset.tab;renderWorkspace();return;}if(btn.dataset.slide){const a=artOf();state.slide=Math.max(0,Math.min(a.slides.length-1,state.slide+Number(btn.dataset.slide)));renderWorkspace();return;}if(btn.dataset.resolve){const c=current()?.comments.find(c=>c.id===btn.dataset.resolve);if(c){c.resolved=!c.resolved;current().approved=false;persist();renderWorkspace();}return;}if(btn.dataset.commentAnchor){const a=artOf();state.tab='preview';if(a?.kind==='ppt')state.slide=Number(btn.dataset.commentAnchor);renderWorkspace();$('#artifactDisplay')?.scrollIntoView({behavior:'smooth',block:'center'});return;}if(btn.dataset.toggleModel){const id=btn.dataset.toggleModel;if(state.crew.includes(id)){if(state.crew.length===1){toast('至少保留一位成员');return;}state.crew=state.crew.filter(x=>x!==id);}else state.crew.push(id);persist();renderTeam();refreshChrome();return;}if(btn.dataset.exportTask){state.current=btn.dataset.exportTask;state.version=current().versions.length-1;exportArtifact();return;}switch(btn.dataset.action){case'new':newDialog();break;case'close':closeDialog();break;case'settings':budgetDialog();break;case'connect':connect();break;case'run':runTask();break;case'edit':editArtifact();break;case'export':exportArtifact();break;case'approve':approve();break;case'workspace':openView('workspace');break;case'team':openView('team');break;case'notifications':toast('没有待处理通知。模型与沙盒配置、任务审批都在 项目协作中。');break;}});
$('#playerStart').onclick=()=>{if(state.view==='runtime'){window.RuntimeUI?.openSettings();return;}if(state.running){state.paused=!state.paused;refreshChrome();if(state.view==='workspace')renderWorkspace();}else runTask();};$('#favoriteCurrent').onclick=()=>{const t=current();if(t)favorite(t.kind);else toast('先选择一个协作方案');};$('#backButton').onclick=()=>openView('discover');$('.brand').onclick=e=>{e.preventDefault();openView('discover');};$('#mainDialog').addEventListener('click',e=>{if(e.target===$('#mainDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});$('#globalSearch').oninput=e=>{state.search=e.target.value;if(!['discover','history','library'].includes(state.view))openView('discover');else if(state.view==='discover')renderHome();else if(state.view==='history')renderHistory();else renderLibrary();};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus();}});
document.getElementById('homeTaskForm')?.addEventListener('submit',async event=>{event.preventDefault();const brief=document.getElementById('homeBrief').value.trim();if(!brief)return;openView('chat');await window.ChatUI?.prepareTask(brief);});
window.Gongming={toast,openView};
renderHome();refreshChrome();
})();
